+  BrowserBridgeSession? session;
+  BrowserBridgeStatus? status;
+  Object? connectError;
+
+  int connectCalls = 0;
+  int? seenPort;
+  bool? seenCopyKeys;
+
+  @override
+  Future<BrowserBridgeSession> connect({
+    int port = bridgeDefaultPort,
+    bool copyKeys = false,
+  }) async {
+    connectCalls++;
+    seenPort = port;
+    seenCopyKeys = copyKeys;
+    final error = connectError;
+    if (error != null) throw error;
+    return session!;
+  }
+
+  @override
+  Future<BrowserBridgeStatus> status() async => status!;
+}
