+              .having(
+                (e) => e.message,
+                'allowed set',
+                contains('default|pi'),
+              ),
+        ),
+      );
+    });
+  });
+
+  group('isTruthyEnvValue', () {
+    test('accepts the repo-wide truthy set, case-insensitive and trimmed',
+        () {
+      for (final v in ['1', 'true', 'yes', 'on', 'TRUE', ' On ', 'Yes']) {
+        expect(isTruthyEnvValue(v), isTrue, reason: '$v should be truthy');
