String renderAppStoreHeaderBadgeHtml(LinksConfig links) => '''
    <a class="store-badge" href="${_escapeAttr(links.appstore)}" target="_blank" rel="noopener" data-store-referral="appstore-header" aria-label="Fa on the App Store">
