import 'dart:convert';

/// One-line `key=value` rendering of tool-call arguments, capped at 100
/// columns.
String formatArgs(Map<String, dynamic> args) {
  var formatted = args.entries
      .map((entry) => '${entry.key}=${safeJsonEncode(entry.value)}')
      .join(', ');
  if (formatted.length > 100) {
    formatted = '${formatted.substring(0, 100)}...';
  }
  return formatted;
}

/// [jsonEncode] that never throws (cyclic/unserializable values degrade to
/// a placeholder).
String safeJsonEncode(Object? value) {
  try {
    return jsonEncode(value);
  } catch (_) {
    return '[unserializable]';
  }
}
/// The `output:` config section (gh-1198): console-output behavior flags.
/// Today only `streamThinking` — the opt-in live thinking stream for
/// line-mode/headless CLI runs (`output.streamThinking`, default false =
/// the byte-identical legacy output).
///
/// Pure Dart (no `dart:io`) so both the boot parser (`cli_config.dart`)
/// and the `config check`/`set` validators (`config_service.dart`) share
/// the SAME strict parser — no mirror to keep in sync.
library;

import 'package:yaml/yaml.dart';

import '../exceptions.dart';

/// The one `output:` key today.
const outputStreamThinkingKey = 'streamThinking';

/// Parses the `output:` section strictly: unknown keys and bad types
/// throw [ConfigException] (a typo must never silently keep the default).
void parseOutputSection(Object? node) {
  if (node == null) return;
  if (node is! YamlMap) {
    throw ConfigException('output must be a map, got: $node');
  }
  for (final key in node.keys) {
    if (key != outputStreamThinkingKey) {
      throw ConfigException('unknown "output" key: $key');
    }
    final value = node[key];
    if (value is! bool) {
      throw ConfigException(
        '"output.$outputStreamThinkingKey" must be a boolean',
      );
    }
  }
}

/// The `output.streamThinking` value of a parsed section: true only when
/// explicitly set (a validated section, absent = false).
bool outputStreamThinkingValue(Object? node) =>
    node is YamlMap && node[outputStreamThinkingKey] == true;
/// Mouse-scroll behaviour for the Fa TUI.
enum TuiMouseMode {
  /// The terminal keeps native text selection; the TUI does not capture
  /// mouse wheel events. Use PgUp/PgDn to scroll the TUI viewport.
  off,

  /// The TUI captures the mouse wheel to scroll its internal viewport.
  /// Most terminals still allow Shift+drag to select text.
  on,

  /// Start with mouse capture enabled and disable it if the terminal does
  /// not send a mouse wheel event within a short probe window.
  auto,
}

/// Parses a user-supplied string into a [TuiMouseMode].
TuiMouseMode parseTuiMouseMode(String? value) {
  final v = value?.trim().toLowerCase();
  return switch (v) {
    '1' || 'true' || 'yes' || 'on' => TuiMouseMode.on,
    '0' || 'false' || 'no' => TuiMouseMode.off,
    _ => TuiMouseMode.auto,
  };
}

