String renderAppStoreHeroCtaHtml(LinksConfig links) => '''
        <a class="btn btn-primary btn-store btn-store-hero" href="${_escapeAttr(links.appstore)}" target="_blank" rel="noopener" data-store-referral="appstore-hero">
